import json,struct
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/sports-integration';OUT.mkdir(parents=True,exist_ok=True);checks=[]
def check(name,value):
 checks.append({'check':name,'passed':bool(value)});print(('PASS ' if value else 'FAIL ')+name,flush=True)
 if not value:raise AssertionError(name)
def read_glb(path):
 data=path.read_bytes();assert data[:4]==b'glTF';size=struct.unpack_from('<I',data,12)[0];return json.loads(data[20:20+size])
