 page.goto('http://127.0.0.1:5173',wait_until='networkidle');page.wait_for_function('window.cityApp?.ready',timeout=90000)
 check('BLK-7 is the western outer parcel at (-252,70)',page.evaluate("cityApp.sportsSite.blockId==='BLK-7'&&cityApp.sportsSite.x===-252&&cityApp.sportsSite.z===70&&cityApp.plan.blocks.find(b=>b.id==='BLK-7').moduleId==='qinghe-sports-field'"))
 check('four original BLK-7 homes removed',page.evaluate("['QR-025','QR-026','QR-027','QR-028'].every(id=>!cityApp.scene.getObjectByName(id))"))
 check('one selectable sports parcel registered',page.evaluate("cityApp.plan.buildings.filter(b=>b.blockId==='BLK-7').length===1&&!!cityApp.scene.getObjectByName('QINGHE-SPORTS')"))
 baseline=(OUT/'city-before-sports.js').read_text(encoding='utf8')
 same=page.evaluate('''async source=>{const T=await import('three'),url=URL.createObjectURL(new Blob([source],{type:'text/javascript'})),m=await import(url);URL.revokeObjectURL(url);const prior=m.buildCity(new T.Scene()).plan.buildings.filter(b=>b.blockId!=='BLK-7'),actual=cityApp.plan.buildings.filter(b=>!b.moduleId);return prior.length===actual.length&&prior.every(b=>actual.some(a=>JSON.stringify(a)===JSON.stringify(b)))}''',baseline)
 check('all other original residences remain unchanged',same)
 check('nine prior city modules and the river remain',page.evaluate("['hospital-campus','skyline-one','mall-complex','shanghai-tower','university-campus','dome-arena','amusement-park','linxu-residential','quiet-city-park'].every(id=>cityApp.plan.buildings.some(b=>b.moduleId===id))&&cityApp.river.manifest.id==='qinglan-river'"))
 check('old BLK-7 furniture absent from instance batches',page.evaluate("cityApp.exportCity('QR-029').batches.every(b=>b.items.every(i=>i.blockId!=='BLK-7'))"))
 bounds=page.evaluate("async()=>{const T=await import('three'),box=new T.Box3();for(const c of cityApp.sports.root.children)if(c.name!=='Qinghe road connections'&&c.name!=='Qinghe city lighting')box.expandByObject(c);return{min:box.min.toArray(),max:box.max.toArray()}}")
 check('112m model fits BLK-7',bounds['min'][0]>=-308.001 and bounds['max'][0]<=-195.999 and bounds['min'][2]>=13.999 and bounds['max'][2]<=126.001)
 check('foundation meets city pedestrian grade',abs(bounds['min'][1]+.06)<.001)
 check('two complete entrances connect existing roads',page.evaluate("['Qinghe public road connection','Qinghe service road connection'].every(n=>cityApp.sports.root.getObjectByName(n))"))
 check('community track and pitch retain original dimensions',page.evaluate('cityApp.sports.manifest.track.lanes===4&&Math.abs(cityApp.sports.manifest.track.insideLaneLength-250.39821765728436)<.001&&cityApp.sports.manifest.pitch.width===42&&cityApp.sports.manifest.pitch.length===68'))
 check('imported semantic groups resolve to the selectable city ID',page.evaluate("[...cityApp.sports.groups.values()].every(g=>g.userData.id==='QINGHE-SPORTS'&&g.userData.component)"))
 page.screenshot(path=str(OUT/'city-overview.png'));page.locator('#sports-view').click();page.wait_for_function('Math.abs(cityApp.controls().target.x+252)<.1&&Math.abs(cityApp.controls().target.z-70)<.1',timeout=45000)
 check('sports shortcut selects and frames BLK-7',page.evaluate("cityApp.state.selected.id==='QINGHE-SPORTS'&&Math.abs(cityApp.controls().target.x+252)<.1&&Math.abs(cityApp.controls().target.z-70)<.1"))
 page.screenshot(path=str(OUT/'sports-context.png'))
 page.locator('#pause').click();time=page.evaluate('cityApp.sports.simulationTime');page.wait_for_timeout(180);check('global pause freezes sports animation',time==page.evaluate('cityApp.sports.simulationTime'))
 page.locator('#pause').click();page.wait_for_timeout(180);check('resume advances sports simulation',page.evaluate('cityApp.sports.simulationTime')>time)
 page.locator('#traffic').uncheck();page.wait_for_timeout(160);check('city traffic toggle controls all sports people and ball',page.evaluate("!cityApp.sports.root.getObjectByName('Runner 0').visible&&!cityApp.sports.root.getObjectByName('Player 0').visible&&!cityApp.sports.root.getObjectByName('Rolling football').visible"));page.locator('#traffic').check()
 page.locator('#sports-runners').evaluate("e=>{e.checked=false;e.dispatchEvent(new Event('change',{bubbles:true}))}");page.wait_for_timeout(160)
 check('independent runner toggle preserves football',page.evaluate("!cityApp.sports.root.getObjectByName('Runner 0').visible&&cityApp.sports.root.getObjectByName('Rolling football').visible"))
 page.locator('#sports-runners').evaluate("e=>{e.checked=true;e.dispatchEvent(new Event('change',{bubbles:true}))}")
 page.locator('#sports-football').evaluate("e=>{e.checked=false;e.dispatchEvent(new Event('change',{bubbles:true}))}");page.wait_for_timeout(160)
 check('independent football toggle preserves runners',page.evaluate("cityApp.sports.root.getObjectByName('Runner 0').visible&&!cityApp.sports.root.getObjectByName('Rolling football').visible"))
 page.locator('#sports-football').evaluate("e=>{e.checked=true;e.dispatchEvent(new Event('change',{bubbles:true}))}")
 page.locator('#quality').select_option('fast');check('city quality reduces sports grass detail',page.evaluate("cityApp.sports.quality==='low'&&cityApp.sports.root.getObjectByName('Individual grass blades').count===2000"));page.locator('#quality').select_option('balanced')
 page.locator('[data-time=night]').click();page.wait_for_function('cityApp.sportsLights.every(l=>l.intensity>3500)',timeout=45000);check('night enables four city-positioned floodlights',page.evaluate('cityApp.sportsLights.length===4&&cityApp.sportsLights.every(l=>l.intensity>3500)'));page.screenshot(path=str(OUT/'sports-night.png'))
 page.locator('[data-time=morning]').click();page.wait_for_function('cityApp.sportsLights.every(l=>l.intensity===0)',timeout=45000);check('day turns floodlights off',page.evaluate('cityApp.sportsLights.every(l=>l.intensity===0)'))
 page.locator('#focus-building').click();page.wait_for_timeout(1900)
 check('architecture view isolates sports module',page.evaluate("cityApp.sports.root.visible&&!cityApp.scene.getObjectByName('SKY-ONE').visible"));page.screenshot(path=str(OUT/'sports-isolated.png'))
 with page.expect_download(timeout=180000) as dl:page.locator('#export-building').click()
 dl.value.save_as(OUT/'QINGHE-SPORTS.glb');doc=read_glb(OUT/'QINGHE-SPORTS.glb');names=[n.get('name','') for n in doc['nodes']]
 check('single GLB includes track grass goals and runners',all(n in names for n in ['QINGHE-SPORTS','Red rubber running track','Individual grass blades','Runner 0','goals']))
 check('single GLB excludes other city modules','SKY-ONE' not in names and 'LINXU-A' not in names)
 snapshot=page.evaluate("(()=>{const m=cityApp.exportCity('QINGHE-SPORTS').modules[0];return{id:m.id,block:m.blockId,space:m.snapshotSpace,objects:m.snapshot.objects.length,owners:[...new Set(m.snapshot.objects.map(o=>o.owner))],finite:m.snapshot.objects.every(o=>o.matrix.every(Number.isFinite))}})()")
 check('sports JSON contains a complete world-space snapshot',snapshot['id']=='qinghe-sports-field' and snapshot['block']=='BLK-7' and snapshot['space']=='world' and snapshot['objects']>22000 and snapshot['finite'] and snapshot['owners']==['QINGHE-SPORTS'])
 page.evaluate("cityApp.select('SKY-ONE')");page.locator('#focus-building').click();page.wait_for_timeout(1900)
 audit=page.evaluate("(()=>{const all=cityApp.exportCity(),s=all.modules.find(m=>m.id==='qinghe-sports-field');return{modules:all.modules.map(m=>m.id),count:s.snapshot.objects.length,hidden:!cityApp.sports.root.visible,quality:cityApp.sports.quality}})()")
 check('full JSON includes sports while another building is isolated',audit['count']>22000 and audit['hidden'] and audit['quality']=='medium' and len(audit['modules'])==11)
 with page.expect_download(timeout=240000) as dl:page.locator('#export').click()
 dl.value.save_as(OUT/'town-with-sports.glb');doc=read_glb(OUT/'town-with-sports.glb');names=[n.get('name','') for n in doc['nodes']]
 check('full GLB retains sports and prior landmarks',all(n in names for n in ['QINGHE-SPORTS','LINXU-A','SKY-ONE','ARENA-DOME','RIVER-QINGLAN','SKYDAY-PARK','SENYIN-PARK']))
 page.locator('#home').click();page.wait_for_timeout(1800);page.locator('[data-view=free]').click();page.wait_for_timeout(150);check('city free camera still works',page.evaluate('cityApp.state.freeView'));page.keyboard.press('Escape')
 page.set_viewport_size({'width':420,'height':880});page.wait_for_timeout(200)
 if page.locator('#panel-content').is_hidden():page.locator('#collapse').click()
 page.locator('#sports-view').click();page.wait_for_function('Math.abs(cityApp.controls().target.x+252)<.1&&Math.abs(cityApp.controls().target.z-70)<.1',timeout=45000)
 check('mobile shortcut selects sports and closes settings',page.locator('#panel-content').is_hidden() and page.evaluate("cityApp.state.selected.id==='QINGHE-SPORTS'&&document.documentElement.scrollWidth===420"))
 page.screenshot(path=str(OUT/'sports-mobile.png'))
 check('no JavaScript or WebGL errors',not errors)
 report={'checks':checks,'errors':errors,'bounds':bounds,'snapshot':snapshot,'metrics':page.evaluate('cityApp.metrics()')};(OUT/'verification.json').write_text(json.dumps(report,indent=2),encoding='utf8');print(json.dumps({'passed':len(checks)}),flush=True);browser.close()
